import { Box, Container, Stack, Typography, useMediaQuery, useTheme } from "@mui/material";
import masterData from "../../data/masterData.json";
import { getIcon } from "../../utils/iconMap";
import LeadFormCard from "./LeadFormCard";
import type { Specialty } from "../../types/fellowship";

interface HeroSectionProps {
  specialty?: Specialty | null;
}

export default function HeroSection({ specialty = null }: HeroSectionProps) {
  const { brand, hero } = masterData;
  const theme = useTheme();
  const isMdUp = useMediaQuery(theme.breakpoints.up("md"));

  const headlineBefore = specialty?.headlineBefore || hero.headlineBefore;
  const headlineHighlight = specialty?.headlineHighlight || hero.headlineHighlight;
  const subheadline = specialty?.subheadline || hero.subheadline;
  const description = specialty?.heroDescription || hero.description;
  const doctorImage = specialty?.heroImage || hero.image;

  return (
    <Box
      sx={{
        position: "relative",
        overflow: "hidden",
        background:
          "linear-gradient(180deg, #EAF3FF 0%, #F5F9FF 35%, #FFFFFF 78%)",
        pb: { xs: 3, md: 0 },
      }}
    >
      {/* soft dots like design */}
      <Box
        sx={{
          position: "absolute",
          inset: 0,
          opacity: 0.22,
          backgroundImage: "radial-gradient(circle, rgba(0,86,210,0.25) 1px, transparent 1px)",
          backgroundSize: "22px 22px",
          pointerEvents: "none",
        }}
      />

      <Container maxWidth="lg" sx={{ position: "relative", zIndex: 2, pt: { xs: 2, md: 2.5 }, pb: { md: 0 } }}>
        <Stack direction="row" alignItems="center" spacing={1.1} sx={{ mb: { xs: 2.5, md: 2 } }}>
          <Box component="img" src={brand.logo} alt={brand.name} sx={{ width: 34, height: 34 }} />
          <Typography sx={{ fontWeight: 800, fontSize: 14, letterSpacing: "0.08em", color: "#0B1F3A" }}>
            {brand.name}
          </Typography>
        </Stack>

        <Box
          sx={{
            position: "relative",
            display: "grid",
            gridTemplateColumns: {
              xs: "1fr",
              md: "1.05fr 0.95fr",
            },
            gap: { xs: 2.5, md: 2 },
            alignItems: "stretch",
            minHeight: { md: 560, lg: 600 },
          }}
        >
          {/* Doctor — full visual center-right behind form */}
          {isMdUp && (
            <Box
              key={doctorImage}
              sx={{
                position: "absolute",
                left: "42%",
                bottom: 0,
                transform: "translateX(-42%)",
                width: { md: 380, lg: 440 },
                height: { md: 540, lg: 600 },
                zIndex: 1,
                pointerEvents: "none",
              }}
            >
              <Box
                component="img"
                src={doctorImage}
                alt={specialty?.name || "Doctor"}
                sx={{
                  width: "100%",
                  height: "100%",
                  objectFit: "contain",
                  objectPosition: "bottom center",
                }}
              />
              <Typography
                sx={{
                  position: "absolute",
                  left: { md: -20, lg: -40 },
                  top: "38%",
                  width: 110,
                  fontFamily: "'Dancing Script', cursive",
                  fontSize: 20,
                  lineHeight: 1.15,
                  color: "#0056D2",
                  fontWeight: 700,
                  transform: "rotate(-10deg)",
                  whiteSpace: "pre-line",
                  textAlign: "center",
                }}
              >
                {hero.scriptText}
              </Typography>
            </Box>
          )}

          {/* Left copy + bottom stats */}
          <Box sx={{ position: "relative", zIndex: 3, pr: { md: 2 }, display: "flex", flexDirection: "column" }}>
            <Typography
              sx={{
                color: "#0056D2",
                fontWeight: 700,
                fontSize: 11,
                letterSpacing: "0.14em",
                mb: 1.5,
              }}
            >
              {specialty ? specialty.name.toUpperCase() : brand.eyebrow}
            </Typography>

            <Typography
              component="h1"
              sx={{
                fontWeight: 800,
                color: "#0B1F3A",
                fontSize: { xs: "1.7rem", sm: "2.1rem", md: "2.35rem", lg: "2.55rem" },
                lineHeight: 1.15,
                mb: 1.5,
                letterSpacing: "-0.02em",
                maxWidth: 520,
              }}
            >
              {headlineBefore}
              <Box component="span" sx={{ color: "#0056D2" }}>
                {headlineHighlight}
              </Box>
            </Typography>

            <Typography sx={{ fontWeight: 700, color: "#0B1F3A", fontSize: { xs: 15, md: 17 }, mb: 1.25 }}>
              {subheadline}
            </Typography>

            <Typography
              sx={{ color: "#5A6B80", fontSize: { xs: 13.5, md: 14.5 }, lineHeight: 1.7, maxWidth: 420, mb: 3 }}
            >
              {description}
            </Typography>

            {!isMdUp && (
              <Box sx={{ display: "flex", justifyContent: "center", my: 1 }}>
                <Box
                  component="img"
                  key={doctorImage}
                  src={doctorImage}
                  alt="Doctor"
                  sx={{ width: "70%", maxWidth: 280, height: 320, objectFit: "contain" }}
                />
              </Box>
            )}

            <Box sx={{ mt: "auto", pb: { md: 3 } }}>
              {/* Stats — single horizontal row like design */}
              <Stack
                direction="row"
                flexWrap="wrap"
                useFlexGap
                spacing={{ xs: 2, md: 2.5 }}
                alignItems="center"
                sx={{ mb: 2 }}
              >
                {hero.stats.map((stat) => {
                  const Icon = getIcon(stat.icon);
                  return (
                    <Stack key={stat.id} direction="row" spacing={0.9} alignItems="center">
                      <Box
                        sx={{
                          width: 34,
                          height: 34,
                          borderRadius: "50%",
                          bgcolor: "#E8F1FF",
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "center",
                        }}
                      >
                        <Icon sx={{ color: "#0056D2", fontSize: 18 }} />
                      </Box>
                      <Typography sx={{ fontSize: 12.5, fontWeight: 700, color: "#0B1F3A" }}>
                        {stat.value ? (
                          <>
                            <Box component="span" sx={{ color: "#0056D2" }}>
                              {stat.value}
                            </Box>{" "}
                            {stat.label}
                          </>
                        ) : (
                          stat.label
                        )}
                      </Typography>
                    </Stack>
                  );
                })}
              </Stack>

              <Stack
                direction="row"
                alignItems="center"
                spacing={1.25}
                sx={{
                  display: "inline-flex",
                  bgcolor: "#fff",
                  border: "1px solid #E0EAF6",
                  borderRadius: "12px",
                  px: 1.5,
                  py: 0.9,
                  boxShadow: "0 4px 16px rgba(0,86,210,0.08)",
                }}
              >
                <Box component="img" src={hero.cpdBadge} alt="CPD" sx={{ width: 38, height: 38 }} />
                <Box>
                  <Typography sx={{ fontSize: 12, fontWeight: 700, color: "#0B1F3A" }}>
                    {hero.cpdLabel}
                  </Typography>
                  {hero.cpdSubLabel && (
                    <Typography sx={{ fontSize: 10, color: "#6B7C93" }}>{hero.cpdSubLabel}</Typography>
                  )}
                </Box>
              </Stack>
            </Box>
          </Box>

          {/* Form */}
          <Box
            sx={{
              position: "relative",
              zIndex: 4,
              display: "flex",
              justifyContent: { xs: "stretch", md: "flex-end" },
              alignItems: "flex-start",
              pt: { md: 1 },
              pb: { md: 3 },
            }}
          >
            <LeadFormCard key={specialty?.id || "default"} defaultSpecialty={specialty?.id || ""} />
          </Box>
        </Box>
      </Container>
    </Box>
  );
}
